/*
 * main.c -- auto-office.exe: builds a self-extracting Office installer.
 *
 * Copyright (c) 2026 SCTG Development - Ronan LE MEILLAT
 * SPDX-License-Identifier: MIT
 *
 * Usage:
 *   auto-office.exe --odt-setup .\setup.exe --xml office-2024.xml --out office-2024.exe
 *
 * The output file is "stub + LZMA2 block + footer" (see common/aofx_format.h).
 * The stub (src/stub/stub.c) is compiled first and embedded into this program
 * as a C array (build/stub_data.c, generated by build.sh), so auto-office.exe
 * is a single self-contained file.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <wchar.h>

#include "../common/aofx_format.h"
#include "../common/aofx_lzma2.h"

/* The stub executable, generated by `xxd -i` (see build.sh). */
extern unsigned char aofx_stub_exe[];
extern unsigned int aofx_stub_exe_len;

#define PROGRAM_VERSION "1.0.0"

/* ------------------------------------------------------------------------ */
/* Small helpers                                                             */
/* ------------------------------------------------------------------------ */

static void print_usage(void) {
  fputs(
      "auto-office " PROGRAM_VERSION
      " - self-extracting Office installer builder\n"
      "Copyright (c) 2026 SCTG Development - Ronan LE MEILLAT (MIT license)\n"
      "\n"
      "Usage:\n"
      "  auto-office.exe --odt-setup <setup.exe> --xml <config.xml> --out "
      "<output.exe> [--level 0-9]\n"
      "\n"
      "Options:\n"
      "  --odt-setup <file>  Office Deployment Tool setup.exe to embed\n"
      "  --xml <file>        Office configuration XML to embed\n"
      "  --out <file>        self-extracting executable to create\n"
      "  --level <0-9>       LZMA2 compression level (default 9, smallest)\n"
      "  --help              show this help\n"
      "\n"
      "When the generated file is run, it extracts both files to a private\n"
      "temporary folder, runs \"setup.exe /configure configuration.xml\", waits\n"
      "for it to finish and deletes the temporary folder.\n",
      stdout);
}

/* Reads a whole file into a malloc'ed buffer. Returns 0 on success. */
static int read_file(const wchar_t *path, uint8_t **data, size_t *size) {
  FILE *file = _wfopen(path, L"rb");
  if (file == NULL) {
    fwprintf(stderr, L"error: cannot open '%ls'\n", path);
    return 1;
  }
  /* _fseeki64/_ftelli64 are used so that files > 2 GiB are measured right. */
  _fseeki64(file, 0, SEEK_END);
  long long length = _ftelli64(file);
  _fseeki64(file, 0, SEEK_SET);
  if (length < 0 || (unsigned long long)length > AOFX_MAX_RAW_SIZE) {
    fwprintf(stderr, L"error: '%ls' is empty-or-too-large\n", path);
    fclose(file);
    return 1;
  }
  uint8_t *buffer = (uint8_t *)malloc(length > 0 ? (size_t)length : 1);
  if (buffer == NULL || fread(buffer, 1, (size_t)length, file) != (size_t)length) {
    fwprintf(stderr, L"error: cannot read '%ls'\n", path);
    free(buffer);
    fclose(file);
    return 1;
  }
  fclose(file);
  *data = buffer;
  *size = (size_t)length;
  return 0;
}

/* Parses "--level N"; returns -1 if the value is not a digit 0..9. */
static int parse_level(const wchar_t *text) {
  if (text[0] >= L'0' && text[0] <= L'9' && text[1] == L'\0') return text[0] - L'0';
  return -1;
}

/* ------------------------------------------------------------------------ */
/* Entry point                                                               */
/* ------------------------------------------------------------------------ */

int wmain(int argc, wchar_t **argv) {
  const wchar_t *setupPath = NULL;
  const wchar_t *xmlPath = NULL;
  const wchar_t *outPath = NULL;
  int level = 9;

  for (int i = 1; i < argc; i++) {
    const wchar_t *arg = argv[i];
    if (wcscmp(arg, L"--help") == 0 || wcscmp(arg, L"-h") == 0) {
      print_usage();
      return 0;
    }
    /* Every other option takes exactly one value. */
    if (i + 1 >= argc) {
      fwprintf(stderr, L"error: option '%ls' needs a value (try --help)\n", arg);
      return 2;
    }
    const wchar_t *value = argv[++i];
    if (wcscmp(arg, L"--odt-setup") == 0) setupPath = value;
    else if (wcscmp(arg, L"--xml") == 0) xmlPath = value;
    else if (wcscmp(arg, L"--out") == 0) outPath = value;
    else if (wcscmp(arg, L"--level") == 0) {
      level = parse_level(value);
      if (level < 0) {
        fwprintf(stderr, L"error: --level must be a digit from 0 to 9\n");
        return 2;
      }
    } else {
      fwprintf(stderr, L"error: unknown option '%ls' (try --help)\n", arg);
      return 2;
    }
  }
  if (setupPath == NULL || xmlPath == NULL || outPath == NULL) {
    print_usage();
    return 2;
  }

  int exitCode = 1;
  uint8_t *setupData = NULL, *xmlData = NULL;
  uint8_t *raw = NULL, *packed = NULL;
  size_t setupSize = 0, xmlSize = 0, rawSize = 0, packedSize = 0;
  FILE *out = NULL;

  if (read_file(setupPath, &setupData, &setupSize)) goto cleanup;
  if (read_file(xmlPath, &xmlData, &xmlSize)) goto cleanup;

  /* Cheap sanity check: every Windows executable starts with "MZ". */
  if (setupSize < 2 || setupData[0] != 'M' || setupData[1] != 'Z') {
    fwprintf(stderr, L"error: '%ls' does not look like a Windows executable\n",
             setupPath);
    goto cleanup;
  }
  if (xmlSize == 0) {
    fwprintf(stderr, L"error: '%ls' is empty\n", xmlPath);
    goto cleanup;
  }

  /* Step 1: put both files in one raw container. */
  AofxEntry entries[2] = {
      {AOFX_ENTRY_SETUP, setupData, setupSize},
      {AOFX_ENTRY_XML, xmlData, xmlSize},
  };
  if (aofx_container_build(entries, 2, &raw, &rawSize)) {
    fwprintf(stderr, L"error: cannot build the archive container\n");
    goto cleanup;
  }

  /* Step 2: compress it with LZMA2. */
  wprintf(L"Compressing %zu bytes with LZMA2 (level %d)...\n", rawSize, level);
  AofxFooter footer;
  memset(&footer, 0, sizeof footer);
  if (aofx_lzma2_compress(raw, rawSize, level, &packed, &packedSize,
                          &footer.lzma2Prop)) {
    fwprintf(stderr, L"error: LZMA2 compression failed\n");
    goto cleanup;
  }

  /* Step 3: fill the footer. */
  memcpy(footer.magic, AOFX_MAGIC, sizeof footer.magic);
  footer.version = AOFX_VERSION;
  footer.entryCount = 2;
  footer.rawSize = rawSize;
  footer.packedSize = packedSize;
  footer.rawCrc32 = aofx_crc32(raw, rawSize);

  /* Step 4: write stub + packed block + footer. */
  out = _wfopen(outPath, L"wb");
  if (out == NULL) {
    fwprintf(stderr, L"error: cannot create '%ls'\n", outPath);
    goto cleanup;
  }
  if (fwrite(aofx_stub_exe, 1, aofx_stub_exe_len, out) != aofx_stub_exe_len ||
      fwrite(packed, 1, packedSize, out) != packedSize ||
      fwrite(&footer, 1, sizeof footer, out) != sizeof footer) {
    fwprintf(stderr, L"error: write error on '%ls'\n", outPath);
    goto cleanup;
  }
  if (fclose(out) != 0) {
    out = NULL;
    fwprintf(stderr, L"error: write error on '%ls'\n", outPath);
    goto cleanup;
  }
  out = NULL;

  wprintf(L"Created '%ls': %zu bytes (payload %zu -> %zu bytes, %.1f%%)\n",
          outPath, (size_t)aofx_stub_exe_len + packedSize + sizeof footer,
          rawSize, packedSize, 100.0 * (double)packedSize / (double)rawSize);
  exitCode = 0;

cleanup:
  if (out != NULL) fclose(out);
  free(setupData);
  free(xmlData);
  free(raw);
  free(packed);
  return exitCode;
}
